def editDistanceWithSwaps(s, t):
    m, n = len(s), len(t)
    INF = m + n
    d = [[0] * (n + 2) for _ in range(m + 2)]
    d[0][0] = INF
    for i in range(m + 1):
        d[i + 1][0] = INF
        d[i + 1][1] = i
    for j in range(n + 1):
        d[0][j + 1] = INF
        d[1][j + 1] = j
    last_row = {}
    for i in range(1, m + 1):
        db = 0
        a = s[i - 1]
        for j in range(1, n + 1):
            i1 = last_row.get(t[j - 1], 0)
            j1 = db
            if a == t[j - 1]:
                cost = 0
                db = j
            else:
                cost = 1
            best = d[i][j] + cost
            v = d[i + 1][j] + 1
            if v < best:
                best = v
            v = d[i][j + 1] + 1
            if v < best:
                best = v
            v = d[i1][j1] + (i - i1 - 1) + 1 + (j - j1 - 1)
            if v < best:
                best = v
            d[i + 1][j + 1] = best
        last_row[a] = i
    return d[m + 1][n + 1]
